    asset_age_years,
    failure_mode,
    detection_method,
    time_to_repair_hours,
    repair_cost_zar,
    is_repeat_failure,
    root_cause_identified,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
